mapper.select:
SELECT enabled
FROM spare_parts
WHERE tenant_id = #{tenantId}
AND id = #{sparePartId}
FOR UPDATE

mapper.insert:
INSERT INTO inventory_transactions (
    tenant_id, warehouse_id, request_id, transaction_no, spare_part_id,
    transaction_type, quantity, reference_type, work_order_id, created_by, note
) VALUES (
    #{log.tenantId}, #{log.warehouseId}, #{log.requestId}, #{log.transactionNo}, #{log.sparePartId},
    'OUTBOUND', #{log.quantity}, 'WORK_ORDER', #{log.workOrderId}, #{log.createdBy}, #{log.note,jdbcType=VARCHAR}
)

mapper.update:
UPDATE warehouse_stock SET quantity = quantity - #{quantity}
WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId} AND spare_part_id = #{sparePartId}
  AND quantity >= #{quantity}

UPDATE work_order_parts wp
JOIN work_orders wo ON wo.id = wp.work_order_id
JOIN spare_parts sp ON sp.id = wp.spare_part_id AND sp.tenant_id = wo.tenant_id
SET wp.issued_quantity = wp.issued_quantity + #{quantity}
WHERE wo.tenant_id = #{tenantId} AND wp.work_order_id = #{workOrderId} AND wp.spare_part_id = #{sparePartId}
  AND wp.issued_quantity <= 99999999999.999 - #{quantity}
